    self._mainCatCellClick = Events.AddListener(Constants.EventNames.MainCatCellClick, Bind(self, self.OnMainCatCellClick))
    SetButtonAction(self.BtnShare, Bind(self, self.OnClickShareHandler_))
end

function PreDownloadCatDisplayDialog:InitData(argument)
    KCookie.Set("UIMainInteractionCatDialog", 1)
    local args = checkTable(argument)
    self._go = args.go
end

function PreDownloadCatDisplayDialog:InitView()
    CfUtils.SetActive(self.BtnShare.gameObject, PreDownloadUtils.IsShowShareButton())
    KTool.SetActive(self.Container, false)
    --CfUtils.ChangeMainCamDefalultBlend(0)
    --local go = RolesShowMgr:GetInteractiveCam("Push_cat")
