    --coroutine.yield(CS.UnityEngine.WaitForSeconds(0.86))
    --CfUtils.ChangeMainCamDefalultBlend(1)
    CfUtils.SetTopActive(true)
    KTool.SetActive(self.Container, true)

    if not isNull(self._go) then
        self._ani = KTool.GetOrAddComponent(self._go, typeof(NamedAnimancerComponent))
        self._ani:TryPlay('idle')
    end
    
    self:StartUpdate()
    
end
