--region handler
function PreDownloadCatDisplayDialog:OnMainCatCellClick()
    --是idle的时候才响应
    if not self._ani:IsPlaying("idle") then
        return
    end

    if self._isAniPlay or isNull(self._go) then
        return
    end
    if self._co then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    local num = math.random(3)
    local state = self._ani:TryPlay(string.format("touch%d", num))
    if not isNull(state) then
        self._isAniPlay = true
        state.Events:SetEndAction(function()
            state.Events:SetEndAction(nil)
            self._isAniPlay = false
            self._ani:TryPlay('idle')
        end)
    end
end

function PreDownloadCatDisplayDialog:OnShareVideoRecordStateHandler_(data)
    local recordState = checkInt(data.state)
    Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true, {
        ['SweetHome'] = recordState ~= 1,
    })
end
--endregion handler

