---注册update事件
function PreDownloadCatDisplayDialog:StartUpdate()
    self._catAniRandomTime = os.time()

    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = Bind(self, self.Update)
        self._behaviourAction = behaviourAction
    end
end

function PreDownloadCatDisplayDialog:OnClickShareHandler_()
    if GameUtils.IsWindow() then
        GameUtils.Toast(localize('请移动至手机端进行分享'))
        return
    end
    
    local catShareTimelineIndex  = math.random(#PreDownloadConstants.CatShareTimelineDefines)
    local catShareTimelineDefine = PreDownloadConstants.CatShareTimelineDefines[catShareTimelineIndex]
    local resultCatData          = PreDownloadMgr:GetPreDownloadComponent():GetCatData()
    local catGeneNameId          = PreDownloadUtils.MakeCatGeneNameId(resultCatData.genes)
    UIModule.OpenDialog({id = Constants.UITypeIds.CommonSharePreviewDialog, parameters = {
        shareType = Constants.ShareType.PRE_DOWNLOAD_CALL,
        videoArgs = {
            videoNameId  = string.format('PreDownload_HomeCat_%s_%d', catGeneNameId, catShareTimelineIndex),
            timelinePath = catShareTimelineDefine.PREFAB,
            tlCameraName = catShareTimelineDefine.CAMERA,
            ---@param timelineIns UnityEngine.GameObject
            ---@param tlDirector UnityEngine.Playables.PlayableDirector
            tlInitCallback = function(timelineIns, tlDirector)
                -- disable sample cat
                local catSampleName = catShareTimelineDefine.CAT_SAMPLE
                local catSampleGo   = timelineIns.transform:Find(catSampleName)
                CfUtils.SetActive(catSampleGo, false)

                -- load result cat
                local timelineCatGo = nil
                cs_coroutine.yield_return(PreDownloadUtils.LoadResultCatModelAsync(function(catGo)
                    timelineCatGo = catGo
                    local catAnimancerComp = timelineCatGo:GetComponent(typeof(NamedAnimancerComponent))
                    if not isNull(catAnimancerComp) then
                        catAnimancerComp.enabled = false
                    end
                end, timelineIns))
                timelineCatGo.transform:SetParent(timelineIns.transform, false)

                -- bind result cat
                local catTrackName = catShareTimelineDefine.CAT_TRACK
                GachaponUtils.BindTimeline(tlDirector, catTrackName, timelineCatGo)
            end
        },
    }})
end


